// Vérifie et normalise la saisie du formulaire avant l'enregistrement.
const f = $input.first().json;
const nombre = (v) => Number(String(v ?? '').replace(',', '.').trim());

const prixMin = nombre(f['Prix minimum (€/kg)']);
const prixMax = nombre(f['Prix maximum (€/kg)']);
if (!(prixMin > 0) || !(prixMax > 0)) throw new Error('Les prix doivent être des nombres positifs (ex. 2,40).');
if (prixMin > prixMax) throw new Error('Le prix minimum est supérieur au prix maximum.');

const date = String(f['Date de la cotation'] ?? '').slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Date invalide : ' + f['Date de la cotation']);

return [{
  json: {
    date_cotation: date,
    marche: f['Marché'],
    origine: f['Origine'],
    variete: String(f['Variété'] ?? '').trim(),
    calibre: String(f['Calibre'] ?? '').trim(),
    prix_min: prixMin,
    prix_max: prixMax,
    source: String(f['Source'] ?? '').trim() || 'RNM FranceAgriMer',
    source_url: String(f['Lien de la source'] ?? '').trim(),
  },
}];

// Rassemble la série hebdomadaire en un seul texte pour l'IA.
const lignes = $input.all().map((i) => i.json).filter((r) => r.semaine);
if (!lignes.length) throw new Error('Aucune cotation en base.');
const tableau = lignes
  .map((r) => `${r.semaine} (${r.cle}) : ${Number(r.prix).toFixed(2)} €/kg, ${r.nb_cotations} cotation(s)`)
  .join('\n');
const d = lignes.at(-1);
const p = lignes.at(-2);
return [{ json: {
  cle_derniere: d.cle,
  donnees: tableau,
  semaine: d.semaine,
  prix: Number(d.prix),
  prix_precedent: p ? Number(p.prix) : null,
} }];

parameters.text:
=Tu es analyste de marché pour des exportateurs de mangues d'Afrique de l'Ouest (Côte d'Ivoire, Sénégal) qui vendent en France.

Voici le prix moyen grossiste de la mangue, semaine par semaine (le plus récent en dernier) :
{{ $json.donnees }}

Écris un commentaire de 3 phrases maximum, en français simple, pour un exportateur :
1. l'évolution de la dernière semaine par rapport à la précédente (en %) ;
2. le niveau actuel par rapport à la moyenne de la période ;
3. un conseil prudent pour la prochaine expédition.

Règles : n'utilise que les chiffres ci-dessus, n'invente aucune cause ni aucun chiffre. S'il n'y a qu'une semaine, dis simplement que la tendance n'est pas encore mesurable. Pas de titre, pas de liste, pas de mise en forme.

