// Garde le texte de l'IA ; s'il est vide (modèle gratuit indisponible ou réponse vide),
// écrit un commentaire simple calculé à partir des seuls chiffres, sans IA.
const p = $('Préparer le prompt').first().json;
const texteIA = String($json.text ?? '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();
if (texteIA) return [{ json: { cle: p.cle_derniere, texte: texteIA, modele: 'openrouter/free' } }];

const fmt = (n) => n.toFixed(2).replace('.', ',');
let texte = `Semaine ${p.semaine.slice(1)} : ${fmt(p.prix)} €/kg en moyenne.`;
if (p.prix_precedent) {
  const v = ((p.prix - p.prix_precedent) / p.prix_precedent) * 100;
  texte += v === 0
    ? ` Prix stable par rapport à la semaine précédente.`
    : ` ${v > 0 ? 'Hausse' : 'Baisse'} de ${Math.abs(v).toFixed(1).replace('.', ',')} % par rapport à la semaine précédente (${fmt(p.prix_precedent)} €/kg).`;
} else {
  texte += " C'est la première semaine suivie : la tendance n'est pas encore mesurable.";
}
return [{ json: { cle: p.cle_derniere, texte, modele: 'calcul automatique (IA indisponible)' } }];

// Met la série PUBLIQUE au format attendu par le site (src/services/marketData.ts).
// Le public voit les prix avec un décalage et seulement la 1re phrase du commentaire :
// la semaine en cours et le commentaire complet sont réservés aux abonnés (workflow 02).
const DECALAGE_SEMAINES = 4; // 0 = tout publier (semaine en cours comprise)

const toutes = $input.all().map((i) => i.json).filter((r) => r.semaine);
const lignes = toutes.slice(0, Math.max(toutes.length - DECALAGE_SEMAINES, 0)).slice(-12);
const derniere = lignes.at(-1) ?? {};
const syntheses = toutes[0]?.syntheses ?? [];

// Commentaire de la dernière semaine PUBLIQUE (pas celui de la semaine en cours), réduit à sa 1re phrase.
const synthese = syntheses
  .filter((y) => derniere.cle && y.cle <= derniere.cle)
  .sort((a, b) => (a.cle < b.cle ? 1 : -1))[0];
const texte = String(synthese?.texte ?? '').trim();
const extrait = texte ? (texte.match(/^.*?[.!?](?=\s|$)/s)?.[0] ?? texte.slice(0, 160)) : null;

return [{
  json: {
    produit: 'mangue',
    marche: toutes.at(-1)?.marches || 'Rungis',
    unite: '€/kg',
    source: 'RNM FranceAgriMer, cotations grossistes saisies chaque semaine',
    points: lignes.map((r) => ({ semaine: r.semaine, prix: Number(r.prix) })),
    extrait,
    decalageSemaines: DECALAGE_SEMAINES,
    majLe: derniere.derniere_date ?? null, // date de la dernière cotation publiée (AAAA-MM-JJ)
    exemple: false,
  },
}];
